INSERT INTO `bot_intents` VALUES (1,_binary '','HOW_TO_APPLY','Чтобы подать заявление, перейдите в раздел \"Мои заявления\" и нажмите кнопку \"Подать новое заявление\". Вам потребуется заполнить анкету и прикрепить необходимые документы.'),(2,_binary '','REQUIRED_DOCUMENTS','Для большинства услуг требуются: паспорт и документы, подтверждающие льготы. Точный список зависит от типа услуги.'),(3,_binary '','FK_LEVELS','ФК — функциональные классы характеризующие способность к передвижению и самообслуживанию, ФК1 — минимальный уровень нуждаемости, ФК2 — средний, ФК3 — высокий, ФК4 — очень высокий (требует срочного вмешательства). Уровень определяет приоритет оказания услуг.'),(4,_binary '','WAITING_TIME','Срок рассмотрения заявления обычно составляет от 5 до 14 рабочих дней. Срочные случаи (ФК4) рассматриваются в приоритетном порядке.'),(5,_binary '','APPLICATION_STATUS','Статусы заявления:\r •  Подано\r •  Одобрено\r • Отклонено\r • Решено'),(6,_binary '','SERVICE_STATUS','Статусы услуг:\r • Запланировано\r • В работе\r • Завершено\r • Отменено'),(8,_binary '','CONTACT_SUPPORT','Если у вас сложный вопрос, вы можете написать администратору или позвонить по телефону горячей линии: +375 (XX) XXX-XX-XX.'),(9,_binary '','WORKING_HOURS','Центр социального обслуживания работает с 8:00 до 17:00 по будням. Выходные — суббота и воскресенье.'),(10,_binary '','GREETING','Здравствуйте! Я — Помощник центра социального обслуживания. Чем я могу вам помочь сегодня?'),(11,_binary '','APPLICATIONS_AND_SERVICES','Для получения социальной услуги необходимо подать заявление, выберите нужный раздел. Я помогу вам разобраться в требованиях, сроках рассмотрения и статусах.'),(12,_binary '','MY_APPLICATIONS','Ниже отображены последние пять ваших заявлений.'),(13,_binary '','SERVICES_INFO','Социальные услуги назначаются только после одобрения вашего заявления.'),(14,_binary '','MY_SERVICES','Ниже отображены последние пять услуг, назначенных вам. Подробную информацию по каждой услуге вы можете посмотреть в личном кабинете на вкладке «Услуги».');
/*!40000 ALTER TABLE `bot_intents` ENABLE KEYS */;
