DROP TABLE IF EXISTS `client_service_feedback`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `client_service_feedback` (
  `id` int NOT NULL AUTO_INCREMENT,
  `comment` text,
  `createdAt` datetime(6) NOT NULL,
  `improvementSuggestions` text,
  `ratingOverall` int NOT NULL,
  `ratingQuality` int NOT NULL,
  `ratingTimeliness` int DEFAULT NULL,
  `ratingWorker` int NOT NULL,
  `wouldRecommend` bit(1) NOT NULL,
  `client_id` int NOT NULL,
  `client_service_id` int NOT NULL,
  `worker_id` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UKnjp69wxxmo36xgr19cydx986t` (`client_service_id`),
  KEY `FKa5r9ylkwaopjwvucny5e3a9k1` (`client_id`),
  KEY `FK51rro5ybh1wjkqmd2jp96yokm` (`worker_id`),
  CONSTRAINT `FK51rro5ybh1wjkqmd2jp96yokm` FOREIGN KEY (`worker_id`) REFERENCES `users` (`id`),
  CONSTRAINT `FK8be8poo7d0if688utjsmeqijp` FOREIGN KEY (`client_service_id`) REFERENCES `client_services` (`id`),
  CONSTRAINT `FKa5r9ylkwaopjwvucny5e3a9k1` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

