INSERT INTO `client_service_feedback` VALUES (1,'Комментарий','2026-02-05 08:41:55.401322','Предложения по улучшению',4,3,5,2,_binary '',41,108,31),(2,'Услуга оказана быстро и профессионально. Специалист подробно объяснил все нюансы.','2026-02-05 10:12:00.000000','Можно добавить возможность отслеживания этапов выполнения услуги.',5,5,5,5,_binary '',44,116,31),(3,'Документы были оформлены корректно, сотрудник проявил внимание к деталям.','2026-03-05 10:18:00.000000','Хотелось бы получать уведомления о готовности документов.',4,4,4,5,_binary '',45,118,32),(4,'Сопровождение прошло отлично, сотрудник помог во всех вопросах.','2026-03-05 10:25:00.000000','Можно улучшить время ожидания в очереди.',5,4,5,5,_binary '',46,120,31),(5,'Консультация была полезной, но не все вопросы удалось прояснить.','2026-03-05 10:31:00.000000','Добавить более подробные инструкции и примеры.',3,3,3,4,_binary '\0',47,122,31),(6,'Сотрудник помог разобраться с бытовыми вопросами, всё прошло спокойно.','2026-04-05 10:40:00.000000','Было бы удобно иметь возможность заранее загрузить документы.',4,4,4,4,_binary '',48,124,31),(7,'Сопровождение в госорганах прошло без проблем, спасибо за помощь.','2026-04-05 10:48:00.000000','Добавить возможность выбора времени сопровождения.',5,5,5,4,_binary '',49,126,31),(8,'Консультация по льготам была понятной и структурированной.','2026-04-05 10:55:00.000000','Хотелось бы получить памятку с основными льготами.',4,4,4,5,_binary '',50,128,31),(9,'Помощь оказана, но некоторые моменты остались непонятными.','2026-05-05 11:02:00.000000','Улучшить качество объяснений и добавить больше примеров.',3,3,3,3,_binary '\0',51,130,32),(10,'Документы оформлены быстро, сотрудник был вежлив и внимателен.','2026-05-05 11:10:00.000000','Можно улучшить удобство записи на приём.',5,5,4,5,_binary '',52,132,31),(11,'Консультация по соцзащите была полезной, специалист ответил на все вопросы.','2026-05-05 11:18:00.000000','Добавить возможность задать уточняющие вопросы онлайн.',4,4,5,4,_binary '',53,134,32),(12,'Всё хорошо','2026-04-13 11:12:10.499826','Всё хорошо',5,5,5,5,_binary '',54,148,31),(13,'Комментарий','2026-05-12 12:15:31.640096','Улучшения',4,3,5,5,_binary '',56,155,31);
